#include <iostream>
#include <vector>

void RemoveMultiplesOf(std::vector<int>& values, int n);

int main()
{
    int count, n;
    while (std::cin >> count >> n)
    {
        std::vector<int> values(count);
        for (int i = 0; i < count; i++)
        {
            std::cin >> values[i];
        }
        RemoveMultiplesOf(values, n);
        for (size_t i = 0; i < values.size(); i++)
        {
            std::cout << values[i] << (i + 1 < values.size() ? " " : "");
        }
        std::cout << "\n";
    }
    return 0;
}

